/* AP Tech Work Station. Credentials stay in memory; Windows owns encrypted storage. */
(() => {
  'use strict';
  const app = document.getElementById('workspace');
  const bridge = window.chrome && window.chrome.webview;
  const s = { supportMessages: [], supportWorkers: [], supportEmployee: '', page: 'overview', native: {}, meta: null, error: '', toast: '', loading: true, jobs: [], clients: [], posts: [], categories: [], tasks: [], leads: [], messages: [], leadId: null, chatError: '', jobForm: false, jobDraft: null, blogDraft: null, frame: null, applications: [], registrations: [], chatDrafts: {}, messageIds: {}, selectedEmployee: '', register: false, attendanceBusy: false, nativeTokenPending: undefined, serverTime: Date.now(), clockStarted: performance.now(), adminSigningOut: false };
  const esc = value => String(value == null ? '' : value).replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
  const icon = name => `<svg width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><use href="/workstation/icons.svg#${name}"></use></svg>`;
  const admin = () => Boolean(s.meta && s.meta.admin);
  const employee = () => s.meta && s.meta.employee;
  const allowed = name => admin() || Boolean(employee() && s.meta.permissions[name]);
  const stamp = value => value ? new Date(value).toLocaleString('en-GB', { timeZone: 'Asia/Dhaka', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : '—';
  const duration = value => { const seconds = Math.max(0, Math.floor(value)); return `${String(Math.floor(seconds / 3600)).padStart(2, '0')}:${String(Math.floor(seconds % 3600 / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`; };
  const money = () => 'Accounts only';
  const native = message => { if (bridge) bridge.postMessage(message); };
  function headers() { return { 'Content-Type': 'application/json', ...(s.native.credential ? { Authorization: `Bearer ${s.native.credential}` } : {}), ...(s.native.pcName ? { 'X-PC-Name': s.native.pcName } : {}), ...(s.native.attendanceToken ? { 'X-Attendance-Token': s.native.attendanceToken } : {}) }; }
  async function request(path, body) {
    const response = await fetch(path, { method: body ? 'POST' : 'GET', headers: headers(), credentials: 'same-origin', cache: 'no-store', ...(body ? { body: JSON.stringify(body) } : {}), signal: AbortSignal.timeout(25000) });
    let data; try { data = await response.json(); } catch { throw new Error('The server returned an invalid response. Check the connection and try again.'); }
    if (!response.ok) { const error = new Error(data.error || `Request failed (${response.status})`); error.code = data.code; error.status = response.status; throw error; }
    return data;
  }
  async function run(action) { s.error = ''; try { await action(); } catch (error) { s.loading = false; s.error = error.message || 'Request failed'; render(); } }
  async function logoutAdmin() {
    if (s.adminSigningOut) return; s.adminSigningOut = true;
    try {
      const csrf = await fetch('/api/auth/csrf', { cache: 'no-store' }).then(r => r.json());
      await fetch('/api/auth/signout', { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ csrfToken: csrf.csrfToken, callbackUrl: '/workstation-app', json: 'true' }), credentials: 'same-origin' });
      s.frame = null; s.page = 'overview'; await bootstrap(false); render();
    } finally { s.adminSigningOut = false; }
  }
  function storeAttendance(value) { s.native.attendanceToken = value || null; if (bridge) { s.nativeTokenPending = value || null; native({ action: 'attendance-token', token: value || null }); } }
  async function bootstrap(redraw = true) {
    const previousProfile = JSON.stringify(s.meta?.officeProfile);
    const hadEmployee = employee();
    s.meta = await request('/api/workstation?view=bootstrap');
    showPresenceCheck();
    s.serverTime = Date.parse(s.meta.serverNow); s.clockStarted = performance.now(); s.loading = false;
    if (hadEmployee && !employee()) { storeAttendance(null); s.messages = []; s.leads = []; s.page = 'attendance'; s.frame = null; }
    if (!s.selectedEmployee || !s.meta.employees.some(item => item.code === s.selectedEmployee) && !(s.meta.administrators || []).some(item => 'admin:' + item.id === s.selectedEmployee)) {
      const hour = new Date(s.serverTime + 6 * 3600000).getUTCHours();
      const shift = hour >= 7 && hour < 15 ? 'MORNING' : hour >= 15 && hour < 23 ? 'EVENING' : 'NIGHT';
      s.selectedEmployee = (s.meta.employees.find(item => item.shiftLabel === shift) || s.meta.employees[0] || {}).code || ((s.meta.administrators || [])[0] ? 'admin:' + s.meta.administrators[0].id : '');
    }
    if (admin() && s.meta.device) await request('/api/workstation', { op: 'embed' });
    if (redraw || previousProfile !== JSON.stringify(s.meta.officeProfile) && s.page === 'office') render();
  }
  async function loadPage() {
    if (!s.meta) return;
    if (['overview', 'projects'].includes(s.page) && allowed('projects')) { const data = await request('/api/workstation?view=jobs'); s.jobs = data.jobs; s.clients = data.clients; }
    if (s.page === 'support') { const support = await request('/api/workstation-support?employeeId=' + encodeURIComponent(s.supportEmployee)); s.supportMessages = support.messages; s.supportWorkers = support.workers; }
    if (s.page === 'blog' && allowed('blog') && !s.frame) { const data = await request('/api/workstation?view=blogs'); s.posts = data.posts; s.categories = data.categories; }
    if (['tasks', 'attendance', 'overview'].includes(s.page) && employee()) { const data = await attendance('status'); s.tasks = data.dailyTasks || []; }
    if (s.page === 'applications' && admin()) { const data = await request('/api/workstation?view=applications'); s.applications = data.applications; s.registrations = data.registrations; }
    if (allowed('chat')) await refreshChat(false);
  }
  async function navigate(page) { s.page = page; s.frame = null; s.error = ''; s.toast = ''; if (page === 'referrals') s.frame = '/referrals'; if (page === 'partners') s.frame = '/accounts/partners'; if (page === 'reports') s.frame = '/work-station'; if (page === 'blog' && admin()) s.frame = '/blog-manager'; render(); await loadPage(); render(); }
  async function attendance(action, extra = {}) {
    const data = await request('/api/device-attendance', { action, pcName: s.native.pcName, ...(action === 'login' || action === 'register' ? {} : { sessionToken: s.native.attendanceToken }), ...extra });
    if (data.sessionToken) storeAttendance(data.sessionToken);
    if (data.shift && s.meta) { s.meta.shift = data.shift; if (data.shift.endedAt) storeAttendance(null); }
    if (data.serverNow) { s.serverTime = Date.parse(data.serverNow); s.clockStarted = performance.now(); }
    return data;
  }
  let chatRefreshing = false, chatSeen = new Set(), chatPrimed = false, soundContext;
  document.addEventListener('pointerdown', () => { try { soundContext = soundContext || new AudioContext(); void soundContext.resume(); } catch {} }, { once: true });
  function messageSound() { if (bridge) { native({ action: 'chat-sound' }); return; } try { if (!soundContext || soundContext.state !== 'running') return; const oscillator = soundContext.createOscillator(), gain = soundContext.createGain(); oscillator.connect(gain); gain.connect(soundContext.destination); oscillator.frequency.value = 740; gain.gain.setValueAtTime(0.12, soundContext.currentTime); gain.gain.exponentialRampToValueAtTime(0.001, soundContext.currentTime + 0.25); oscillator.start(); oscillator.stop(soundContext.currentTime + 0.25); } catch {} }
  async function refreshChat(partial = true) {
    if (chatRefreshing) return; chatRefreshing = true; try {
    if (!allowed('chat')) return;
    const data = await request('/api/workstation-chat'); s.leads = data.leads;
    const incoming = s.leads.flatMap(lead => lead.messages.filter(message => message.sender === 'GUEST').map(message => message.id));
    if (chatPrimed && incoming.some(id => !chatSeen.has(id))) messageSound();
    incoming.forEach(id => chatSeen.add(id)); chatPrimed = true;
    if (s.leadId && !s.leads.some(lead => lead.id === s.leadId)) { s.leadId = null; s.messages = []; }
    if (s.leadId) {
      try { const detail = await request(`/api/workstation-chat?leadId=${encodeURIComponent(s.leadId)}`); s.messages = detail.messages; s.chatError = ''; }
      catch (error) { s.chatError = error.message; s.messages = []; }
    }
    if (partial && s.page === 'chat' && document.getElementById('chat-feed')) {
      const feed = document.getElementById('chat-feed'), atBottom = feed.scrollHeight - feed.scrollTop - feed.clientHeight < 90; document.getElementById('chat-threads').innerHTML = chatThreads(); feed.innerHTML = chatFeed(); if (atBottom) feed.scrollTop = feed.scrollHeight; bindThreads();
    }
    document.querySelectorAll('[data-chat-count]').forEach(el => { el.textContent = String(s.leads.filter(lead => lead.messages[0] && lead.messages[0].sender === 'GUEST').length); });
    } finally { chatRefreshing = false; }
  }
  function shiftTime() {
    const shift = s.meta && s.meta.shift; if (!shift) return { seconds: 0, remaining: 28800, extra: 0 };
    const now = s.serverTime + performance.now() - s.clockStarted;
    const end = shift.endedAt ? Date.parse(shift.endedAt) : now;
    const seconds = Math.max(0, (end - Date.parse(shift.startedAt)) / 1000 - shift.breakSeconds - (shift.breakStartedAt ? (end - Date.parse(shift.breakStartedAt)) / 1000 : 0));
    return { seconds: Math.min(28800, seconds), remaining: Math.max(0, 28800 - seconds, (Date.parse(shift.scheduledEndAt) - end) / 1000), extra: 0 };
  }
  function hero() {
    const shift = s.meta.shift; if (!employee() || !shift) return loginPanel(); const time = shiftTime();
    return `<section class="ws-hero"><div><div class="ws-hero-kicker"><span class="ws-dot"></span>${shift.breakStartedAt ? 'On a break' : 'Your shift is in progress'}</div><div class="ws-clock"><b id="shift-clock">${duration(time.seconds)}</b><span>/ 08:00:00</span></div><p class="ws-muted"><span id="shift-remaining">${duration(time.remaining)}</span> remaining · breaks excluded</p></div><div class="ws-hero-side"><span class="ws-pill">${esc(employee().shiftLabel)} · end ${stamp(shift.scheduledEndAt)}</span><button class="ws-btn ws-btn-primary" data-attendance="${shift.breakStartedAt ? 'resume' : 'break'}">${icon(shift.breakStartedAt ? 'Play' : 'Coffee')}${shift.breakStartedAt ? 'Resume shift' : 'Take a break'}</button></div><div class="ws-progress" role="progressbar" aria-label="Attendance target" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100, Math.floor(time.seconds / 288))}"><div id="shift-progress" style="width:${Math.min(100, time.seconds / 288)}%"></div></div><div class="ws-progress-label"><span>Checked in ${stamp(shift.startedAt)}</span><span>Daily timer capped at 8 hours</span></div></section>`;
  }
  function loginPanel() {
    const isAdmin = s.selectedEmployee.startsWith('admin:');
    const people = [...(s.meta.administrators || []).map(person => ({ value: 'admin:' + person.id, label: person.name + ' · ' + (person.role === 'SUPER_ADMIN' ? 'Super Admin' : person.role === 'CEO' ? 'CEO' : 'Admin') })), ...s.meta.employees.map(person => ({ value: person.code, label: person.name + ' · ' + person.shiftLabel }))];
    return `<section class="ws-panel"><div class="ws-panel-head"><div><h2>Choose your profile</h2><p class="ws-muted">Employees, Admin, Super Admin and CEO use this same profile list. Website roles are shown as recorded; selecting a name does not grant access.</p></div></div><form id="attendance-login" class="ws-formgrid">${s.register ? '<label class="ws-field">Your name<input class="ws-input" name="name" required maxlength="80" autocomplete="name"></label>' : `<label class="ws-field">User / employee profile<select class="ws-input" name="code" required>${people.length ? people.map(person => `<option value="${esc(person.value)}" ${person.value === s.selectedEmployee ? 'selected' : ''}>${esc(person.label)}</option>`).join('') : '<option value="">No approved accounts yet</option>'}</select></label>`}${!isAdmin || s.register ? '<label class="ws-field">Attendance password<input class="ws-input" type="password" name="password" autocomplete="off" required maxlength="100"></label>' : '<p class="ws-muted">Continue to verify your website password and any required security code.</p>'}<div class="ws-inline ws-span"><button class="ws-btn ws-btn-primary" type="submit" ${s.attendanceBusy ? 'disabled' : ''}>${s.register ? 'Request account' : isAdmin ? 'Continue to secure login' : 'Login / start attendance'}</button><button class="ws-btn" type="button" data-register>${s.register ? 'Back to login' : 'Request a new account'}</button></div></form></section>`;

  }
  function overview() {
    if (employee() && ['ACCOUNTS','OPERATIONS','MANAGER','FRONT_DESK'].includes(s.meta.officeProfile?.role)) return `${hero()}<section class=ws-panel><h2>${esc(s.meta.officeProfile.role.replaceAll('_',' '))} workspace</h2><p class=ws-muted>${esc(s.meta.officeProfile.units.join(' · ').replaceAll('_',' '))}</p><p>Accounts alone handles money. Reception, work orders and stock are shown according to your assigned role.</p><button class=ws-btn data-page=office>Open Business Office</button></section>`;
    if (admin()) return `<div class="ws-statgrid"><section class="ws-stat"><span>Office management</span><strong>Business units & roles</strong><button class="ws-btn" data-page="office">Open Business Office</button></section><section class="ws-stat"><span>Money records</span><strong>Accounts only</strong></section><section class="ws-stat"><span>Website conversations open</span><strong>${s.leads.length}</strong></section></div><section class="ws-panel"><div class="ws-panel-head"><h2>Recent jobs & projects</h2><button class="ws-btn ws-btn-primary" data-page="projects">New entry / manage</button></div>${jobTable(s.jobs.slice(0, 8))}</section>`;
    return `${hero()}${employee() ? `<div class="ws-grid"><section class="ws-panel"><div class="ws-panel-head"><h2>${employee().shiftLabel === 'EVENING' ? 'Morning handover' : 'Today’s work'}</h2><button class="ws-linkbtn" data-page="tasks">Open tasks ${icon('ArrowUpRight')}</button></div>${employee().shiftLabel === 'NIGHT' ? '<p class="ws-muted">No daily checklist tonight. You’re available for customer messages.</p>' : s.tasks.slice(0, 4).map(task => `<div class="ws-taskrow"><span class="ws-check">${icon(task.done ? 'Check' : 'FileText')}</span><div class="ws-tasktext">${esc(task.title)}<small>${task.day} · ${esc(task.reason || task.status)}</small></div><span class="ws-pill">${task.status}</span></div>`).join('') || '<p class="ws-muted">No pending work assigned.</p>'}</section><section class="ws-panel"><div class="ws-panel-head"><h2>Visitor inbox</h2><button class="ws-linkbtn" data-page="chat">Open chat</button></div>${s.leads.slice(0, 3).map(lead => `<button class="ws-message" data-lead="${esc(lead.id)}"><span class="ws-avatar">${esc(lead.name.slice(0, 2).toUpperCase())}</span><span><strong>${esc(lead.name)}</strong><p>${esc(lead.subject)}</p></span></button>`).join('') || '<p class="ws-muted">No open conversations.</p>'}</section></div>` : ''}`;
  }
  function attendancePanel() {
    if (!employee()) return loginPanel(); const shift = s.meta.shift;
    return `${hero()}<section class="ws-panel"><h2>Work notes & handover</h2><form id="notes-form" class="ws-formgrid ws-section-gap"><label class="ws-field ws-span">Current task / completed work<textarea class="ws-input" name="task" rows="3" maxlength="1000">${esc(shift.task || '')}</textarea></label><label class="ws-field ws-span">Handover for the next shift<textarea class="ws-input" name="handover" rows="3" maxlength="2000">${esc(shift.handover || '')}</textarea></label><div class="ws-inline ws-span"><button class="ws-btn ws-btn-primary">Save notes</button><button type="button" class="ws-btn" data-end-shift>End shift / logout</button></div></form><p class="ws-profile-note">Closing the window does not end attendance. Logout never stops activity tracking.</p></section>`;
  }
  function tasksPanel() {
    if (!employee()) return loginPanel();
    if (employee().shiftLabel === 'NIGHT') return '<section class="ws-panel ws-night"><h2>No daily checklist tonight.</h2><p class="ws-muted">Your shift is available for visitor/customer messages. Attendance and activity tracking remain independent.</p><div><button class="ws-btn ws-btn-primary" data-page="chat">Open visitor chat</button></div></section>';
    return `<section class="ws-panel"><div class="ws-panel-head"><div><h2>${employee().shiftLabel === 'EVENING' ? 'Your morning handover queue' : 'Morning primary checklist'}</h2><p class="ws-muted">One shared task per day. Hold/Pending backlog carries forward. Night has no checklist.</p></div><button class="ws-btn" data-refresh>Refresh</button></div>${s.tasks.map(task => `<div class="ws-taskrow"><span class="ws-check">${icon(task.done ? 'Check' : 'FileText')}</span><div class="ws-tasktext">${esc(task.title)}<small>${task.day} · ${esc(task.reason || task.status)}</small></div><button class="ws-linkbtn" data-task="${esc(task.id)}">${task.status} ${icon('ChevronDown')}</button></div>${s.taskId === task.id ? `<form class="ws-task-detail task-form" data-id="${esc(task.id)}"><label class="ws-field">Published work link<input class="ws-input" name="proofUrl" type="url" value="${esc(task.proofUrl || '')}" maxlength="2000" placeholder="https://…"></label><label class="ws-field">Reason / handover (required for Hold or Cancel)<textarea class="ws-input" rows="2" name="reason" maxlength="1000">${esc(task.reason || '')}</textarea></label><div class="ws-inline"><button class="ws-btn ws-btn-primary" name="status" value="COMPLETED">Complete</button><button class="ws-btn" name="status" value="HOLD">Hold</button><button class="ws-btn" name="status" value="CANCELLED">Cancel / not needed</button><button class="ws-btn ws-btn-quiet" name="status" value="PENDING">Reopen</button></div></form>` : ''}`).join('') || '<p class="ws-muted">No pending work for this shift.</p>'}<p class="ws-profile-note">Every change records the employee and reason. A completion tick is self-reported.</p></section>`;
  }
  function jobTable(jobs = s.jobs) { return `<div class="ws-tablewrap"><table class="ws-table"><thead><tr><th>Work / source</th><th>Client</th><th>Project value</th><th>Status</th><th></th></tr></thead><tbody>${jobs.map(job => `<tr><td>${esc(job.title)}<small>${esc(job.externalSource || 'Website')} · ${esc(job.entry.entryKind || 'PROJECT')}</small></td><td>${esc(job.client && job.client.companyName || job.externalName || '—')}<small>${esc(job.entry.employeeName || '')}</small></td><td class="ws-value">${money(job)}<small>${job.clientCurrency}</small></td><td>${esc(job.status)}</td><td>${admin() ? `<button class="ws-linkbtn" data-frame="/jobs/${encodeURIComponent(job.id)}">Manage ${icon('ArrowUpRight')}</button>` : ''}</td></tr>`).join('')}</tbody></table></div>${jobs.length ? '' : '<p class="ws-muted">No visible projects yet.</p>'}`; }
  function projectsPanel() {
    const draft = s.jobDraft || { title: '', source: 'Fiverr', clientName: '', amount: '', currency: 'USD', entryKind: 'PROJECT', orderId: '', description: '', clientId: '' };
    return `${s.jobForm ? `<section class="ws-panel"><div class="ws-panel-head"><h2>New job or project</h2><button class="ws-btn" data-close-job>Cancel entry</button></div><form id="job-form" class="ws-formgrid"><label class="ws-field">Project / task title<input class="ws-input" name="title" required minlength="2" maxlength="200" value="${esc(draft.title)}"></label><label class="ws-field">Entry type<select class="ws-input" name="entryKind"><option value="PROJECT">Project</option><option value="TASK" ${draft.entryKind === 'TASK' ? 'selected' : ''}>Task</option></select></label><label class="ws-field">Source<select class="ws-input" name="source">${['Fiverr', 'Upwork', 'Freelancer', 'Website', 'Direct'].map(source => `<option ${source === draft.source ? 'selected' : ''}>${source}</option>`).join('')}</select></label><label class="ws-field">Client name<input class="ws-input" name="clientName" required maxlength="120" value="${esc(draft.clientName)}"></label><label class="ws-field">Value · Accounts only<input class="ws-input" type="number" min="0" max="999999999.99" step="0.01" name="amount" readonly value="0"></label><label class="ws-field">Currency<select class="ws-input" name="currency"><option>USD</option><option ${draft.currency === 'BDT' ? 'selected' : ''}>BDT</option></select></label><label class="ws-field">Existing Hub client (optional)<select class="ws-input" name="clientId"><option value="">External / not linked yet</option>${s.clients.map(client => `<option value="${esc(client.id)}" ${draft.clientId === client.id ? 'selected' : ''}>${esc(client.companyName || client.contactName)}</option>`).join('')}</select></label><label class="ws-field">Order / reference ID<input class="ws-input" name="orderId" maxlength="120" value="${esc(draft.orderId)}"></label><label class="ws-field ws-span">Scope / notes<textarea class="ws-input" rows="3" name="description" maxlength="10000">${esc(draft.description)}</textarea></label><div class="ws-inline ws-span"><button class="ws-btn ws-btn-primary">Save project entry</button><p class="ws-muted">Creates a draft Hub job. No invoice or payout is created.</p></div></form></section>` : ''}<section class="ws-panel ws-section-gap"><div class="ws-panel-head"><div><h2>${admin() ? 'All jobs & projects' : 'My project entries'}</h2><p class="ws-muted">Maximum 200 records · values stay in their original currency.</p></div><div class="ws-inline"><button class="ws-btn ws-btn-primary" data-new-job>${icon('Plus')}New entry</button>${admin() ? '<button class="ws-btn" data-frame="/jobs">Full job manager</button>' : ''}</div></div>${jobTable()}</section>`;
  }
  function blogPanel() {
    if (s.blogDraft) { const draft = s.blogDraft; return `<section class="ws-panel"><div class="ws-panel-head"><h2>${draft.id ? 'Edit draft post' : 'New blog post'}</h2><button class="ws-btn" data-close-blog>Back to posts</button></div><form id="blog-form" class="ws-formgrid"><label class="ws-field ws-span">Title<input class="ws-input" name="title" required minlength="3" maxlength="180" value="${esc(draft.title || '')}"></label><label class="ws-field ws-span">Summary<textarea class="ws-input" name="excerpt" rows="2" maxlength="1000">${esc(draft.excerpt || '')}</textarea></label><label class="ws-field ws-span">Content<textarea class="ws-input ws-editor-body" name="content" required minlength="10" maxlength="100000">${esc(draft.content || '')}</textarea></label><div class="ws-inline ws-span"><label class="ws-btn">Add article image<input class="ws-image-file" type="file" accept="image/jpeg,image/png,image/webp,image/avif" data-blog-image="article"></label><input class="ws-input" name="articleImageAlt" aria-label="Article image description" maxlength="300" value="${esc(draft.articleImageAlt || '')}" placeholder="Describe the article image before adding"><small>JPG, PNG, WebP or AVIF · up to 4 MB</small></div><label class="ws-field ws-span">Thumbnail (optional)<input class="ws-input" name="coverImageUrl" type="url" placeholder="HTTPS image link, or upload below" value="${esc(draft.coverImageUrl || '')}"></label>${draft.coverImageUrl ? `<img class="ws-cover-preview ws-span" src="${esc(draft.coverImageUrl)}" alt="${esc(draft.coverImageAlt || '')}">` : ''}<div class="ws-span"><label class="ws-btn">Upload thumbnail<input class="ws-image-file" type="file" accept="image/jpeg,image/png,image/webp,image/avif" data-blog-image="cover"></label><span id="blog-upload-status" role="status"></span></div><label class="ws-field ws-span">Primary tag (optional)<input class="ws-input" name="primaryKeyword" maxlength="80" value="${esc(draft.primaryKeyword || (draft.tags || [])[0] || '')}" placeholder="One main topic"></label><label class="ws-field ws-span">Extra keywords (optional)<input class="ws-input" name="secondaryKeywords" maxlength="500" value="${esc(draft.secondaryKeywords || '')}" placeholder="Comma separated, maximum four"></label><p class="ws-muted ws-span">Author: ${esc(employee() ? employee().name : s.meta.admin.name)}</p><p class="ws-muted ws-span">Title and summary fill the search listing automatically. Blank summary is generated from your article.</p><div class="ws-inline ws-span"><button class="ws-btn" name="review" value="no">Save draft</button><button class="ws-btn ws-btn-primary" name="review" value="yes">Submit for review</button></div></form></section>`; }
    return `<div class="ws-admin-note">${icon('ShieldCheck')}Employees write, edit and submit their own drafts. Admins review and publish.</div><section class="ws-panel"><div class="ws-panel-head"><h2>Blog manager</h2><button class="ws-btn ws-btn-primary" data-new-blog>New post</button></div>${s.posts.map(post => `<article class="ws-entrycard"><div class="ws-entrycopy"><strong>${esc(post.title)}</strong><small>${esc(post.category && post.category.name || 'No category')} · ${stamp(post.updatedAt)}</small></div><span class="ws-pill">${post.status === 'DRAFT' && post.reviewRequested ? 'In review' : post.status}</span>${post.status === 'DRAFT' ? `<button class="ws-btn" data-edit-blog="${esc(post.id)}">Edit</button>` : '<span class="ws-muted">Admin review required</span>'}</article>`).join('') || '<p class="ws-muted">No posts created in this employee account yet.</p>'}</section>`;
  }
  function applicationsPanel() { return `<section class="ws-panel"><div class="ws-panel-head"><h2>Programmer signups</h2><button class="ws-btn" data-frame="/accounts/workers">Review signups in Hub</button></div>${s.registrations.map(person => `<div class="ws-entrycard"><span class="ws-avatar">${esc(person.name.slice(0, 2).toUpperCase())}</span><div class="ws-entrycopy"><strong>${esc(person.name)}</strong><small>${esc(person.profession || 'Programmer')} · ${esc(person.email)}</small></div><span class="ws-pill">Pending approval</span></div>`).join('') || '<p class="ws-muted">No pending programmer signups.</p>'}</section><section class="ws-panel ws-section-gap"><h2>Job applications</h2>${s.applications.map(item => `<div class="ws-entrycard"><div class="ws-entrycopy"><strong>${esc(item.user.name)}</strong><small>${esc(item.job.title)} · ${esc(item.deliveryEstimate || 'No estimate')}</small><p class="ws-muted">${esc(item.message || '')}</p></div><button class="ws-btn" data-frame="/jobs/${encodeURIComponent(item.job.id)}/applications">Review application</button></div>`).join('') || '<p class="ws-muted ws-section-gap">No pending job applications.</p>'}</section>`; }
  function chatThreads() { return s.leads.map(lead => `<button class="ws-thread" data-lead="${esc(lead.id)}" aria-pressed="${lead.id === s.leadId}"><strong>${esc(lead.name)}</strong><small>${esc(lead.subject)}</small><small>${esc(lead.messages[0] ? lead.messages[0].body.slice(0, 85) : 'No messages yet')}</small><small>${lead.owner.employeeName ? `Assigned: ${esc(lead.owner.employeeName)}` : 'Unassigned'}</small></button>`).join('') || '<p class="ws-muted">No open visitor chats.</p>'; }
  function chatFeed() { return s.chatError ? `<p class="ws-muted">${esc(s.chatError)}</p>` : s.messages.map(message => `<div class="ws-bubble ${message.sender === 'ADMIN' ? 'mine' : ''}">${esc(message.body)}<small>${message.sender === 'ADMIN' ? 'Support - ' + esc(message.supportName || 'AP Tech') : 'Visitor'} · ${stamp(message.createdAt)}</small><button class="ws-linkbtn" data-delete-request="${esc(message.id)}">Request deletion</button></div>`).join(''); }
  function chatPanel() { const lead = s.leads.find(item => item.id === s.leadId); return `<div class="ws-chat-layout"><aside class="ws-panel"><div class="ws-panel-head"><h2>Website inbox</h2><button class="ws-linkbtn" data-refresh>Refresh</button></div><div class="ws-threadlist" id="chat-threads">${chatThreads()}</div></aside><section class="ws-panel">${lead ? `<div class="ws-chat-top"><div><h2>${esc(lead.name)}</h2><p class="ws-muted">${esc(lead.subject)}</p></div><span class="ws-pill">Live inbox · automatic updates</span></div><div class="ws-inline ws-section-gap"><button class="ws-btn" data-chat-action="claim">Take conversation</button><button class="ws-btn" data-chat-action="release">Release / hand over</button><button class="ws-btn" data-chat-action="resolve">Resolve</button></div><div class="ws-chat-feed" id="chat-feed" role="log" aria-label="Visitor conversation">${chatFeed()}</div><form id="chat-compose" class="ws-compose"><input class="ws-input" name="body" aria-label="Customer reply" maxlength="5000" required placeholder="Write a reply…" value="${esc(s.chatDrafts[s.leadId] || '')}"><button class="ws-btn ws-btn-primary">${icon('Send')}Send</button></form><p class="ws-profile-note">Replies go to this website customer. Existing Hub private conversations are separate.</p>` : '<h2>Select a visitor conversation</h2><p class="ws-muted ws-section-gap">Take an unassigned conversation or one handed over by an offline worker.</p>'}</section></div>`; }
  function settingsPanel() { return `<section class="ws-panel"><h2>Activity tracking</h2><p class="ws-muted ws-section-gap">Sends PC name and active/idle snapshots. The visible Chrome extension sends approved work-site counters. No background typed text, screenshots or clipboard is read.</p><form id="tracking-form" class="ws-section-gap"><label class="ws-checkline"><input type="checkbox" name="consent" required>I have read the notice and agree to start this activity session.</label><label class="ws-checkline ws-section-gap"><input type="checkbox" name="remember" ${s.native.rememberConsent ? 'checked' : ''}>Remember consent and resume tracking when the app starts.</label><div class="ws-inline ws-section-gap"><button class="ws-btn ws-btn-primary" ${!bridge ? 'disabled' : ''}>Start / resume tracking</button><button class="ws-btn" type="button" data-pause-tracking>Pause tracking</button></div></form><p class="ws-muted ws-section-gap">${esc(s.native.syncStatus || 'Waiting for native tracker status')}</p></section><section class="ws-panel ws-section-gap"><h2>Software & browser extension</h2><div class="ws-inline ws-section-gap"><button class="ws-btn" data-update ${!bridge ? 'disabled' : ''}>Check for software updates</button><a class="ws-btn" href="/downloads/work-tracker/APTechChromeExtension.zip" target="_blank" rel="noopener">Chrome extension download</a></div><p class="ws-muted ws-section-gap">App ${esc(s.native.appVersion || 'browser mode')} · Microsoft WebView2 · PC ${esc(s.native.pcName || 'unknown')}</p></section>`; }
  function pairingPanel() { return `<section class="ws-panel ws-loggedout"><h2>Connect this PC</h2><p class="ws-muted">Paste the one-time PC credential from Hub → Work Station. Employee names will then appear automatically.</p><form id="pair-form"><label class="ws-field">Device credential<input class="ws-input" type="password" name="credential" required pattern="[a-f0-9]{64}" autocomplete="off"></label><button class="ws-btn ws-btn-primary ws-section-gap" ${!bridge ? 'disabled' : ''}>Pair PC</button></form>${!bridge ? '<p class="ws-muted">Open the installed Windows app for device pairing and activity controls.</p>' : ''}<button class="ws-btn" data-admin-login>Administrator website login</button><button class="ws-btn" data-partner-login>Employee / partner website login</button></section>`; }
  function supportPanel() {
    return '<section class="ws-panel"><h2>Super Admin support</h2>' + (s.supportWorkers.length ? '<select id="support-worker" class="ws-input"><option value="">Choose worker</option>' + s.supportWorkers.map(worker=>'<option value="'+esc(worker.id)+'" '+(worker.id===s.supportEmployee?'selected':'')+'>'+esc(worker.name)+'</option>').join('')+'</select>' : '') + '<div id="support-feed" class="ws-chat-feed">'+s.supportMessages.map(message=>'<div class="ws-bubble"><strong>'+esc(message.name)+'</strong><p>'+esc(message.body)+'</p><small>'+stamp(message.createdAt)+'</small><button class="ws-linkbtn" data-support-delete="'+esc(message.id)+'">Request deletion</button></div>').join('')+'</div><form id="support-form"><input name="body" class="ws-input" required maxlength="5000" placeholder="Message Super Admin"><button class="ws-btn ws-btn-primary">Send</button></form><button data-refresh class="ws-linkbtn">Refresh</button></section>';
  }
  function bindThreads() { document.querySelectorAll('[data-lead]').forEach(button => button.onclick = () => void run(async () => { s.page = 'chat'; s.leadId = button.dataset.lead; s.chatError = ''; await refreshChat(false); render(); })); }
  function render() {
    const name = employee() ? employee().name : admin() ? s.meta.admin.name : 'Not signed in';
    const initials = name.split(' ').slice(0, 2).map(part => part[0] || '').join('');
    const menu = [{ id: 'overview', label: 'Overview', icon: 'LayoutDashboard', show: true }, { id: 'attendance', label: 'My shift', icon: 'Clock3', show: Boolean(s.meta && s.meta.device) }, { id: 'tasks', label: 'Daily tasks', icon: 'ListChecks', show: Boolean(employee()) }, { id: 'support', label: 'Super Admin', icon: 'MessagesSquare', show: Boolean(employee() || s.meta?.admin?.role === 'SUPER_ADMIN') }, { id: 'chat', label: 'Visitor chat', icon: 'MessagesSquare', show: allowed('chat') }, { id: 'projects', label: 'Jobs & projects', icon: 'BriefcaseBusiness', show: allowed('projects') }, { id: 'blog', label: 'Blog manager', icon: 'NotebookPen', show: allowed('blog') }, { id: 'applications', label: 'Applications', icon: 'FileUser', show: admin() }, { id: 'referrals', label: 'Referral partners', icon: 'Handshake', show: admin() }, { id: 'partners', label: 'Partners', icon: 'Handshake', show: admin() }, { id: 'reports', label: 'Staff & reports', icon: 'User', show: admin() }, { id: 'office', label: 'Business Office', icon: 'BriefcaseBusiness', show: Boolean(admin() || employee()) }, { id: 'settings', label: 'Settings', icon: 'Settings', show: true }].filter(item => item.show);
    if (!menu.some(item => item.id === s.page)) { s.page = 'overview'; s.frame = null; }
    const headings = { support: 'Super Admin support', overview: admin() ? 'Your business, connected.' : `Welcome${employee() ? ', ' + employee().name : ' to Work Station'}.`, attendance: 'Your shift, at a glance.', tasks: 'A clear plan for today.', chat: 'Every conversation, together.', projects: 'Every job. One workspace.', blog: 'Create content that matters.', applications: 'Find the right programmers.', referrals: 'Referral partners & applications.', partners: 'Build better partnerships.', reports: 'Staff, attendance & records.', office: 'Your role. Your business workspace.', settings: 'Your Work Station settings.' };
    let content = '';
    if (s.loading) content = '<section class="ws-panel">Connecting to AP Tech Hub…</section>';
    else if (!s.meta || !s.meta.device) content = pairingPanel();
    else if (s.frame && admin()) content = `<section><div class="ws-panel-head"><span class="ws-pill">Secure Hub management · signed in as ${esc(s.meta.admin.name)}</span><button class="ws-btn" data-frame-back>Back to Work Station</button></div><iframe class="ws-admin-frame" title="Hub management" src="${esc(s.frame)}"></iframe></section>`;
    else if (s.page === 'office') content = '<div id=business-office class=office-root></div>';
    else content = ({ overview, support: supportPanel, attendance: attendancePanel, tasks: tasksPanel, projects: projectsPanel, blog: blogPanel, chat: chatPanel, applications: applicationsPanel, settings: settingsPanel }[s.page] || overview)();
    app.innerHTML = `<div class="ws-titlebar"><span class="ws-inline"><span class="ws-titlebrand">AP TECH / WORK STATION</span><span>· ${esc(s.native.appVersion || 'Windows app')}</span></span><div class="ws-inline"><button class="ws-btn ws-btn-quiet" data-update ${!bridge ? 'disabled' : ''}>${icon('Download')}Update</button>${admin() ? '<button class="ws-btn" data-admin-logout>Admin logout</button>' : ''}</div></div><div class="ws-shell"><aside class="ws-sidebar"><div class="ws-brand"><img class="ws-app-logo" src="/app-icons/icon-192.png" alt="AP Tech logo"><div>Work Station<small>AP TECH AGENCY</small></div></div><nav class="ws-nav">${menu.map(item => `<button class="ws-navbtn" data-page="${item.id}" aria-pressed="${s.page === item.id}">${icon(item.icon)}${item.label}${item.id === 'chat' ? '<span class="ws-count" data-chat-count>0</span>' : ''}</button>`).join('')}</nav><div class="ws-sidebar-bottom"><div class="ws-track"><span class="ws-inline"><span class="ws-dot"></span><span id="tracking-state">${s.native.tracking ? 'Activity tracking on' : 'Tracking paused'}</span></span><button data-pause-tracking>Pause tracking</button></div><div>PC: ${esc(s.meta && s.meta.device ? s.meta.device.name : s.native.pcName || 'Unpaired')}<br>Employee: ${esc(employee() ? employee().name : 'Not in attendance')}</div>${employee() ? '<button class="ws-linkbtn" data-end-shift>End attendance / logout</button>' : ''}</div></aside><main class="ws-main"><header class="ws-top"><div><div class="ws-eyebrow">AP TECH HUB · BANGLADESH TIME</div><h1>${esc(headings[s.page])}</h1><p class="ws-muted">${admin() ? 'Administrator session · normal website permissions apply' : 'Your work, conversations and shift — in one place.'}</p></div><div class="ws-person"><span class="ws-avatar">${esc(initials)}</span><div>${esc(name)}<small>${admin() ? 'Website administrator' : employee() ? (s.meta.officeProfile?.role || 'SALES').replaceAll('_',' ') + ' · ' + employee().shiftLabel : 'Attendance login required'}</small></div></div></header><div class="ws-identity"><span>PC name<strong>${esc(s.meta && s.meta.device ? s.meta.device.name : 'Unpaired')}</strong> · ${esc(s.native.pcName || '—')}</span><span>On-shift employee<strong>${esc(employee() ? employee().name : 'Not signed in')}</strong></span></div>${s.error ? `<p class="ws-error" role="alert">${esc(s.error)}</p>` : ''}${content}${s.toast ? `<p class="ws-toast" role="status">${esc(s.toast)}</p>` : ''}<footer class="ws-bottomline"><span id="connection-state">${s.meta ? 'Connected to AP Tech Hub' : 'Not connected'}</span><span>Activity collection and attendance are independent.</span></footer></main></div>`;
    bind(); tick(); if (s.page === 'office' && window.mountBusinessOffice) void window.mountBusinessOffice(document.getElementById('business-office'), request);
  }
  function bind() {
    app.querySelectorAll('[data-page]').forEach(button => button.onclick = () => void run(() => navigate(button.dataset.page)));
    app.querySelectorAll('[data-frame]').forEach(button => button.onclick = () => { const path = button.dataset.frame; if (admin() && /^\/(jobs|blog-manager|accounts\/(partners|workers)|work-station|referrals)(\/|$|\?)/.test(path)) { s.frame = path; render(); } });
    app.querySelector('[data-frame-back]')?.addEventListener('click', () => { s.frame = null; if (s.page === 'partners' || s.page === 'referrals' || s.page === 'reports') s.page = 'overview'; render(); });
    app.querySelectorAll('[data-partner-login]').forEach(button => button.onclick = () => native({ action: 'partner-login' }));
    app.querySelectorAll('[data-admin-login]').forEach(button => button.onclick = () => { const selected = app.querySelector('#attendance-login select[name=code]'); if (!selected || !selected.value.startsWith('admin:')) { s.page = 'attendance'; if (!s.meta?.device) s.error = 'Pair this PC first to load administrator and employee names.'; render(); return; } if (bridge) native({ action: 'admin-login', accountId: selected.value.slice(6) }); else window.location.assign('/login?workstationAdmin=' + encodeURIComponent(selected.value.slice(6))); });
    app.querySelector('[data-admin-logout]')?.addEventListener('click', () => void run(logoutAdmin));
    app.querySelectorAll('[data-update]').forEach(button => button.onclick = () => native({ action: 'check-updates' }));
    app.querySelectorAll('[data-pause-tracking]').forEach(button => button.onclick = () => { native({ action: 'pause-tracking' }); s.toast = 'Activity tracking paused. Attendance is unchanged.'; render(); });
    app.querySelector('[data-register]')?.addEventListener('click', () => { s.register = !s.register; render(); });
    app.querySelector('#attendance-login select[name=code]')?.addEventListener('change', event => { s.selectedEmployee = event.target.value; render(); });
    app.querySelector('#support-worker')?.addEventListener('change', event=>void run(async()=>{s.supportEmployee=event.target.value;await loadPage();render();}));
    app.querySelectorAll('[data-support-delete]').forEach(button=>button.onclick=()=>void run(async()=>{await request('/api/workstation-support',{action:'request-delete',employeeId:s.supportEmployee||undefined,messageId:button.dataset.supportDelete});s.toast='Deletion requested';render();}));
    const supportForm=app.querySelector('#support-form');if(supportForm)supportForm.onsubmit=event=>{event.preventDefault();const body=String(new FormData(supportForm).get('body')||'');void run(async()=>{await request('/api/workstation-support',{employeeId:s.supportEmployee||undefined,body});await loadPage();render();});};
    const login = app.querySelector('#attendance-login'); if (login) login.onsubmit = event => { event.preventDefault(); if (s.attendanceBusy) return; const selected = String(new FormData(login).get('code') || ''); if (!s.register && selected.startsWith('admin:')) { if (bridge) native({ action: 'admin-login', accountId: selected.slice(6) }); else window.location.assign('/login?workstationAdmin=' + encodeURIComponent(selected.slice(6))); return; } s.attendanceBusy = true; const values = new FormData(login); login.querySelector('button[type=submit]').disabled = true; s.selectedEmployee = String(values.get('code') || ''); const registering = s.register; void run(async () => { try { if (admin()) await logoutAdmin(); const data = await attendance(registering ? 'register' : 'login', registering ? { name: String(values.get('name')), password: String(values.get('password')) } : { code: s.selectedEmployee, password: String(values.get('password')) }); if (data.message) { s.toast = data.message; s.register = false; } else { s.page = 'tasks'; s.tasks = data.dailyTasks || []; } await bootstrap(false); render(); } finally { s.attendanceBusy = false; const submit = document.querySelector('#attendance-login button[type=submit]'); if (submit) submit.disabled = false; } }); };
    app.querySelectorAll('[data-attendance]').forEach(button => button.onclick = () => void run(async () => { await attendance(button.dataset.attendance); render(); }));
    app.querySelectorAll('[data-end-shift]').forEach(button => button.onclick = () => void run(async () => { const time = shiftTime(); if (!confirm('Record your departure? Save work notes first. Device activity tracking will continue.')) return; const reason = time.remaining > 0 ? prompt('Eight hours excluding breaks / scheduled end are incomplete. Enter an early-leave reason (required):') : ''; if (time.remaining > 0 && !reason) return; await attendance('logout', reason ? { earlyLeaveReason: reason } : {}); s.page = 'attendance'; await bootstrap(false); s.toast = 'Departure recorded. Activity tracking is unchanged.'; render(); }));
    const notes = app.querySelector('#notes-form'); if (notes) notes.onsubmit = event => { event.preventDefault(); const values = new FormData(notes); void run(async () => { await attendance('task', { task: String(values.get('task')), handover: String(values.get('handover')) }); s.toast = 'Work notes saved.'; render(); }); };
    app.querySelectorAll('[data-task]').forEach(button => button.onclick = () => { s.taskId = s.taskId === button.dataset.task ? null : button.dataset.task; render(); });
    app.querySelectorAll('.task-form').forEach(form => form.onsubmit = event => { event.preventDefault(); const values = new FormData(form); const status = event.submitter.value; const reason = String(values.get('reason')).trim(); void run(async () => { if (['HOLD', 'CANCELLED'].includes(status) && !reason) throw new Error('A reason is required for Hold or Cancel.'); const data = await attendance('checklist', { taskId: form.dataset.id, status, reason, proofUrl: String(values.get('proofUrl')).trim() }); s.tasks = data.dailyTasks; s.taskId = null; s.toast = 'Task status saved with your employee identity.'; render(); }); });
    app.querySelectorAll('[data-delete-request]').forEach(button=>button.onclick=()=>void run(async()=>{await request('/api/workstation-chat',{action:'request-delete',leadId:s.leadId,messageId:button.dataset.deleteRequest});s.toast='Deletion requested. Admin approval is required.';render();}));
    app.querySelectorAll('[data-refresh]').forEach(button => button.onclick = () => void run(async () => { await loadPage(); render(); }));
    app.querySelector('[data-new-job]')?.addEventListener('click', () => { s.jobForm = true; s.jobDraft = null; s.jobOperationId = crypto.randomUUID(); render(); });
    app.querySelector('[data-close-job]')?.addEventListener('click', () => { s.jobForm = false; s.jobDraft = null; render(); });
    const job = app.querySelector('#job-form'); if (job) job.onsubmit = event => { event.preventDefault(); s.jobDraft = Object.fromEntries(new FormData(job)); void run(async () => { const data = { ...s.jobDraft, ...(s.jobDraft.clientId ? {} : { clientId: undefined }), operationId: s.jobOperationId }; await request('/api/workstation', { op: 'job', data }); s.jobForm = false; s.jobDraft = null; s.toast = 'Draft Hub job created. No invoice or payout was generated.'; await loadPage(); render(); }); };
    app.querySelector('[data-new-blog]')?.addEventListener('click', () => { s.blogDraft = {}; s.blogOperationId = crypto.randomUUID(); render(); });
    app.querySelectorAll('[data-edit-blog]').forEach(button => button.onclick = () => { s.blogDraft = { ...s.posts.find(post => post.id === button.dataset.editBlog) }; s.blogOperationId = crypto.randomUUID(); render(); });
    app.querySelector('[data-close-blog]')?.addEventListener('click', () => { s.blogDraft = null; render(); });
    function insertArticleImage(form, url) {
      if (!/^https:\/\//i.test(url)) throw new Error('Use an HTTPS image URL');
      const alt = form.elements.articleImageAlt.value; if (!alt?.trim()) throw new Error('Describe the article image before adding');
      const body = form.elements.content; const markdown = '\n\n![' + alt.trim().replace(/[\[\]\r\n]/g, ' ') + '](' + url.replace(/\)/g, '%29') + ')\n';
      body.value += markdown; body.dispatchEvent(new Event('change')); if (!body.hidden) body.focus();
    }
    app.querySelectorAll('[data-blog-image]').forEach(input => input.onchange = async () => {
      const file = input.files[0], form = app.querySelector('#blog-form'); if (!file || !form) return;
      const status = document.getElementById('blog-upload-status');
      const buttons = [...form.querySelectorAll('button[name=review]')]; buttons.forEach(button => button.disabled = true); input.disabled = true; status.textContent = ' Uploading image…';
      try {
        if (input.dataset.blogImage === 'article' && !form.elements.articleImageAlt.value.trim()) throw new Error('Describe the article image before adding');
        if (file.size > 4 * 1024 * 1024) throw new Error('Choose an image smaller than 4 MB');
        const payload = new FormData(); payload.append('file', file); const authHeaders = headers(); delete authHeaders['Content-Type'];
        const response = await fetch('/api/blog-image', { method: 'POST', headers: authHeaders, credentials: 'same-origin', body: payload, signal: AbortSignal.timeout(45000) });
        const data = await response.json(); if (!response.ok || !data.attachment?.fileUrl) throw new Error(data.error || 'Image upload failed');
        if (!form.isConnected) return;
        if (input.dataset.blogImage === 'cover') {
          form.elements.coverImageUrl.value = data.attachment.fileUrl;
          let preview = form.querySelector('.ws-cover-preview'); if (!preview) { preview = document.createElement('img'); preview.className = 'ws-cover-preview ws-span'; preview.alt = 'Cover image preview'; form.elements.coverImageUrl.closest('label').after(preview); } preview.src = data.attachment.fileUrl;
          form.elements.coverImageAlt.focus();
        } else insertArticleImage(form, data.attachment.fileUrl);
        status.textContent = ' Image uploaded.';
      } catch (error) { if (form.isConnected) status.textContent = ' ' + error.message; }
      finally { input.disabled = false; input.value = ''; buttons.forEach(button => button.disabled = false); }
    });
    const blog = app.querySelector('#blog-form'); if (blog && window.workstationBlogEditor) window.workstationBlogEditor.mount(blog.elements.content); if (blog) blog.onsubmit = event => { event.preventDefault(); const values = Object.fromEntries(new FormData(blog)); s.blogDraft = { ...s.blogDraft, ...values }; void run(async () => { const data = { operationId: s.blogOperationId, ...(s.blogDraft.id ? { id: s.blogDraft.id } : {}), title: values.title, content: values.content, excerpt: values.excerpt, categoryId: values.categoryId || null, metaDescription: values.excerpt, primaryKeyword: values.primaryKeyword, secondaryKeywords: values.secondaryKeywords, coverImageUrl: values.coverImageUrl, coverImageAlt: values.coverImageAlt, submitReview: event.submitter.value === 'yes' }; await request('/api/workstation', { op: 'blog', data }); s.blogDraft = null; s.toast = data.submitReview ? 'Draft submitted for administrator review.' : 'Draft saved.'; await loadPage(); render(); }); };
    bindThreads();
    app.querySelectorAll('[data-chat-action]').forEach(button => button.onclick = () => void run(async () => { if (button.dataset.chatAction === 'resolve' && !confirm('Resolve this customer conversation? A new visitor message will reopen it.')) return; await request('/api/workstation-chat', { action: button.dataset.chatAction, leadId: s.leadId }); await refreshChat(false); render(); }));
    const compose = app.querySelector('#chat-compose'); if (compose) { compose.elements.body.oninput = () => { s.chatDrafts[s.leadId] = compose.elements.body.value; }; compose.onsubmit = event => { event.preventDefault(); const id = s.leadId; const body = compose.elements.body.value.trim(); if (!body) return; s.chatDrafts[id] = body; s.messageIds[id] = s.messageIds[id] || crypto.randomUUID(); void run(async () => { await request('/api/workstation-chat', { action: 'send', leadId: id, messageId: s.messageIds[id], body }); s.chatDrafts[id] = ''; delete s.messageIds[id]; await refreshChat(false); render(); }); }; }
    const pair = app.querySelector('#pair-form'); if (pair) pair.onsubmit = event => { event.preventDefault(); const credential = pair.elements.credential.value.trim(); void run(async () => { const previous = s.native.credential; s.native.credential = credential; try { await bootstrap(false); } catch (error) { s.native.credential = previous; throw error; } native({ action: 'pair', credential }); s.page = 'settings'; render(); }); };
    const tracking = app.querySelector('#tracking-form'); if (tracking) tracking.onsubmit = event => { event.preventDefault(); native({ action: 'start-tracking', consent: tracking.elements.consent.checked, remember: tracking.elements.remember.checked }); };
    document.querySelectorAll('[data-chat-count]').forEach(el => { el.textContent = String(s.leads.filter(lead => lead.messages[0] && lead.messages[0].sender === 'GUEST').length); });
  }
  function showPresenceCheck() {
    const presence = s.meta && s.meta.presence;
    const previous = document.getElementById('presence-check');
    if (!presence || !presence.required) { if (previous) previous.remove(); return; }
    if (previous) return;
    const dialog = document.createElement('dialog');
    dialog.id = 'presence-check';
    dialog.innerHTML = '<h2>Are you still working?</h2><p>Your attendance has been active for 12 hours. Confirm within 2 minutes to stay signed in.</p><button class="ws-btn ws-btn-primary">Yes, I am active</button>';
    document.body.appendChild(dialog);
    dialog.addEventListener('cancel', event => event.preventDefault());
    dialog.querySelector('button').onclick = () => void run(async () => { await attendance('confirm-active'); dialog.remove(); await bootstrap(false); render(); });
    dialog.showModal();
  }
  function tick() { const time = shiftTime(); [['shift-clock', duration(Math.min(28800, time.seconds))], ['shift-remaining', duration(time.remaining)], ['shift-extra', duration(time.extra)]].forEach(([id, value]) => { const el = document.getElementById(id); if (el) el.textContent = value; }); const bar = document.getElementById('shift-progress'); if (bar) bar.style.width = `${Math.min(100, time.seconds / 288)}%`; }
  setInterval(tick, 1000);
  let supportPolling = false;
  setInterval(async () => {
    if (s.page !== 'support' || supportPolling || !s.meta) return;
    supportPolling = true;
    try {
      const data = await request('/api/workstation-support?employeeId=' + encodeURIComponent(s.supportEmployee));
      const feed = document.getElementById('support-feed');
      if (feed && JSON.stringify(data.messages) !== JSON.stringify(s.supportMessages)) {
        s.supportMessages = data.messages;
        feed.innerHTML = data.messages.map(message => '<div class="ws-bubble"><strong>'+esc(message.name)+'</strong><p>'+esc(message.body)+'</p><small>'+stamp(message.createdAt)+'</small><button class="ws-linkbtn" data-support-delete="'+esc(message.id)+'">Request deletion</button></div>').join('');
        feed.querySelectorAll('[data-support-delete]').forEach(button => button.onclick = () => void run(async () => {await request('/api/workstation-support',{action:'request-delete',employeeId:s.supportEmployee||undefined,messageId:button.dataset.supportDelete});s.toast='Deletion requested';render();}));
      }
    } catch (error) { s.error = error.message; }
    finally { supportPolling = false; }
  }, 5000);
  setInterval(() => { if (allowed('chat')) void refreshChat().catch(error => { const status = document.getElementById('connection-state'); if (status) status.textContent = `Chat disconnected: ${error.message}`; }); }, 2000);
  setInterval(() => { if (s.meta && !s.attendanceBusy) void bootstrap(false).then(() => { if (['overview', 'attendance'].includes(s.page) && !document.querySelector('textarea:focus,input:focus')) render(); }).catch(error => { const status = document.getElementById('connection-state'); if (status) status.textContent = `Connection unavailable: ${error.message}`; }); }, 30000);
  if (bridge) {
    bridge.addEventListener('message', event => {
      const data = event.data; if (!data || data.kind !== 'native-state') return;
      const previous = s.native; const incomingToken = data.attendanceToken || null;
      const acceptedToken = s.nativeTokenPending !== undefined && incomingToken !== s.nativeTokenPending ? previous.attendanceToken : incomingToken;
      if (incomingToken === s.nativeTokenPending) s.nativeTokenPending = undefined;
      s.native = { ...data, attendanceToken: acceptedToken };
      const label = document.getElementById('tracking-state'); if (label) label.textContent = data.tracking ? 'Activity tracking on' : 'Tracking paused';
      if (s.loading || previous.credential !== data.credential || previous.attendanceToken !== acceptedToken) void run(async () => { await bootstrap(false); await loadPage(); render(); });
    });
    native({ action: 'ready' });
  } else { void run(async () => { await bootstrap(false); await loadPage(); render(); }); }
  render();
})();
